package stack

import (
	"bytes"
	"fmt"
	"os"
	"strconv"

	"go.yaml.in/yaml/v3"

	"hli/internal/compat"
)

// GeneratedHeader starts every generated file (T-2).
const GeneratedHeader = "# GENERATED by hli from stack.yml. Do not edit: change stack.yml and run `hli apply`.\n"

// UnpinnedError is returned when a component has no recorded tag and digest.
type UnpinnedError struct{ App string }

func (e *UnpinnedError) Error() string {
	return fmt.Sprintf("app %q has no pinned image tag and digest; verify one and record it in docs/COMPATIBILITY.md and internal/compat", e.App)
}

type composeFile struct {
	Name     string             `yaml:"name"`
	Services map[string]service `yaml:"services"`
}

type service struct {
	Image       string            `yaml:"image"`
	User        string            `yaml:"user,omitempty"`
	Restart     string            `yaml:"restart"`
	Environment map[string]string `yaml:"environment"`
	Volumes     []string          `yaml:"volumes"`
	Ports       []string          `yaml:"ports"`
}

// Generated holds the rendered Compose and .env files.
type Generated struct {
	Compose []byte
	Env     []byte
}

// Generate renders the Compose project from state and pins. Output depends only
// on its inputs, so the same stack.yml always yields byte-identical files.
func Generate(s *State, pins compat.Pins, u User) (Generated, error) {
	cf := composeFile{Name: s.Project, Services: map[string]service{}}
	for _, app := range s.OrderedApps() {
		c, ok := pins.Lookup(app)
		if !ok {
			return Generated{}, &UnpinnedError{App: app}
		}
		cf.Services[app] = buildService(app, c)
	}

	var buf bytes.Buffer
	buf.WriteString(GeneratedHeader)
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(cf); err != nil {
		return Generated{}, fmt.Errorf("encode compose: %w", err)
	}
	if err := enc.Close(); err != nil {
		return Generated{}, fmt.Errorf("encode compose: %w", err)
	}

	env := GeneratedHeader +
		"PUID=" + strconv.Itoa(u.UID) + "\n" +
		"PGID=" + strconv.Itoa(u.GID) + "\n" +
		"TZ=" + s.Timezone + "\n" +
		"DATA_ROOT=" + s.DataRoot() + "\n" +
		"BIND_ADDRESS=" + s.BindAddress + "\n"

	return Generated{Compose: buf.Bytes(), Env: []byte(env)}, nil
}

// buildService maps one pinned component to a Compose service. Every media app
// mounts the shared data root at /data so imports can hardlink (S-1).
func buildService(app string, c compat.Component) service {
	svc := service{
		Image:       c.Image.Ref(),
		Restart:     "unless-stopped",
		Environment: map[string]string{"TZ": "${TZ}"},
		Volumes:     []string{"./config/" + app + ":/config"},
		Ports:       []string{fmt.Sprintf("${BIND_ADDRESS}:%d:%d", c.Port, c.Port)},
	}
	if c.LinuxServer {
		svc.Environment["PUID"] = "${PUID}"
		svc.Environment["PGID"] = "${PGID}"
	} else {
		svc.User = "${PUID}:${PGID}"
	}
	if usesData(app) {
		svc.Volumes = append(svc.Volumes, "${DATA_ROOT}:/data")
	}
	if app == "jellyfin" {
		svc.Volumes = append(svc.Volumes, "./cache/jellyfin:/cache")
	}
	return svc
}

func usesData(app string) bool {
	return app != "prowlarr"
}

// DataMount is the container path of the shared data root.
const DataMount = "/data"

// MediaDirs are the folders under the data root that M0 creates and wires.
var MediaDirs = map[string]string{
	"movies": "media/movies",
	"tv":     "media/tv",
}

// ContainerPath returns the in-container path of a media dir.
func ContainerPath(kind string) string { return DataMount + "/" + MediaDirs[kind] }

// WriteGenerated writes the files, skipping any whose content is unchanged.
func WriteGenerated(s *State, g Generated) error {
	if err := writeIfChanged(s.ComposePath(), g.Compose, 0o644); err != nil {
		return err
	}
	return writeIfChanged(s.EnvPath(), g.Env, 0o644)
}

func writeIfChanged(path string, data []byte, mode os.FileMode) error {
	if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, data) {
		return nil
	}
	if err := os.WriteFile(path, data, mode); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}
